const CATEGORIES = ['All', 'Pottery', 'Textiles', 'Woodwork', 'Jewelry'] as const;

export default function ShopPage() {
  const { products } = useLoaderData() as { products: Product[] };
  const [searchParams, setSearchParams] = useSearchParams();
  const initialCategory = searchParams.get('category') ?? 'all';
  const [activeCategory, setActiveCategory] = useState(
    initialCategory === 'all' ? 'All' : initialCategory.charAt(0).toUpperCase() + initialCategory.slice(1)
  );

  useEffect(() => {
    const cat = searchParams.get('category');
    if (!cat) {
      setActiveCategory('All');
    } else {
      setActiveCategory(cat.charAt(0).toUpperCase() + cat.slice(1));
    }
  }, [searchParams]);

  const filtered =
    activeCategory === 'All'
      ? products
      : products.filter((p) => p.category === activeCategory.toLowerCase());

  const handleFilter = (cat: string) => {
    setActiveCategory(cat);
    if (cat === 'All') {
      setSearchParams({});
    } else {
      setSearchParams({ category: cat.toLowerCase() });
    }
  };

  return (
    <>
      <Helmet>
        <title>Our Collection — Artisan Goods Co.</title>
        <meta
          name="description"
          content="Browse handcrafted pottery, textiles, woodwork, and jewelry. Every piece made with care by skilled artisans."
        />
