            <p className="text-xs font-semibold uppercase tracking-widest text-primary mb-3">
              Handmade with intention
            </p>
            <h1 className="font-heading text-4xl md:text-5xl font-bold text-foreground leading-tight mb-4">
              Our Collection
            </h1>
            <p className="text-muted-foreground text-lg max-w-xl leading-relaxed">
              Each piece is made by hand, one at a time. Browse our full range of pottery, textiles, woodwork, and jewelry.
            </p>
          </motion.div>
        </div>
      </section>

      {/* Filters + Grid */}
      <section className="py-12 px-6">
        <div className="container mx-auto max-w-6xl">
          {/* Category Filter Pills */}
          <div className="flex flex-wrap gap-2 mb-10">
            {CATEGORIES.map((cat) => (
              <button
                key={cat}
                onClick={() => handleFilter(cat)}
                className={`px-5 py-2 rounded-full text-sm font-medium transition-all duration-150 border ${
                  activeCategory === cat
                    ? 'bg-primary text-primary-foreground border-primary shadow-sm'
                    : 'bg-card text-foreground/70 border-border hover:border-primary/50 hover:text-foreground'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>

          {/* Product Count */}
          <p className="text-sm text-muted-foreground mb-6">
            {filtered.length} {filtered.length === 1 ? 'piece' : 'pieces'} found
          </p>

          {/* Product Grid */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {filtered.map((product, i) => (
              <ProductCard key={product.id} product={product} index={i} />
            ))}
          </div>

          {filtered.length === 0 && (
            <div className="text-center py-20">
              <p className="text-muted-foreground text-lg">No pieces found in this category.</p>
            </div>
          )}
        </div>
      </section>
    </>
  );
}

